INSERT INTO `cms_articles` (`id`, `shop_id`, `public_id`, `blog_id`, `category_id`, `slug`, `title`, `subtitle`, `excerpt`, `body_html`, `body_json`, `cover_media_id`, `locale`, `author_name`, `author_title`, `author_media_id`, `author_admin_id`, `medically_reviewed_by`, `reviewed_at`, `next_review_due`, `read_time_minutes`, `status`, `is_featured`, `published_at`, `scheduled_at`, `is_indexable`, `view_count`, `current_version`, `preview_token`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,1,'8158537d-bd09-11f1-979d-38142846fb09',1,1,'how-to-layer-a-morning-routine','How to layer a morning routine','Thinnest to thickest, and sunscreen last.','The order you apply things in changes how much of each one actually reaches your skin. Here is the rule, and the three places people usually get it wrong.','<p>The rule is simple enough to remember: <strong>thinnest to thickest, sunscreen last</strong>. Everything else is detail.</p><h2>The order</h2><ol><li><strong>Cleanser</strong> — lukewarm water, thirty seconds, no scrubbing.</li><li><strong>Watery treatments</strong> — anything that runs off your fingers.</li><li><strong>Serum</strong> — the active you are actually there for.</li><li><strong>Moisturiser</strong> — seals the layers under it.</li><li><strong>Sunscreen</strong> — always last, always the full amount.</li></ol><h2>Where it goes wrong</h2><p><strong>Not enough sunscreen.</strong> Two fingers\' length for the face and neck. Most people use a third of what they need and get a third of the protection.</p><p><strong>Rushing between layers.</strong> Give each one a minute. A serum that has not absorbed cannot do anything under a moisturiser.</p><p><strong>Too many actives at once.</strong> One is usually enough in the morning. Save the rest for the evening, or for a different day.</p><p><em>This is a seeded draft. Edit it, have it reviewed, then publish.</em></p>',NULL,NULL,'en-IN','Veylor','Formulation team',NULL,NULL,NULL,NULL,NULL,3,'draft',0,NULL,NULL,1,0,1,NULL,'2026-09-30 19:59:54','2026-09-30 19:59:54',NULL);
/*!40000 ALTER TABLE `cms_articles` ENABLE KEYS */;
UNLOCK TABLES;

