/*!40000 ALTER TABLE `cms_faqs` DISABLE KEYS */;
INSERT INTO `cms_faqs` (`id`, `shop_id`, `group_id`, `entity_type`, `entity_id`, `question`, `answer`, `claim_id`, `sort_order`, `is_published`, `is_indexable`, `helpful_count`, `created_at`, `updated_at`) VALUES (1,1,2,NULL,NULL,'How long does delivery take?','Two to four working days in metro cities and four to seven elsewhere. Remote pin codes can take up to ten. You get a tracking link as soon as the parcel leaves us.',NULL,0,1,1,0,'2026-09-30 19:59:54','2026-09-30 19:59:54'),(2,1,2,NULL,NULL,'Is delivery free?','Free on prepaid orders above Rs 999. Below that a flat charge applies, and it is shown at checkout before you pay.',NULL,1,1,1,0,'2026-09-30 19:59:54','2026-09-30 19:59:54'),(3,1,3,NULL,NULL,'Can I return a product I have opened?','Only if it reached you damaged or is faulty. Skincare is sealed for hygiene, so an opened product cannot go back into stock. If something is wrong with it, tell us within 48 hours with a photo and we will replace it.',NULL,0,1,1,0,'2026-09-30 19:59:54','2026-09-30 19:59:54'),(4,1,3,NULL,NULL,'When do I get my refund?','Within five to seven working days of the product reaching us and being checked. It goes back to the way you paid. For cash on delivery orders we refund to a bank account you give us.',NULL,1,1,1,0,'2026-09-30 19:59:54','2026-09-30 19:59:54'),(5,1,4,NULL,NULL,'Which payment methods do you accept?','UPI, credit and debit cards, net banking and wallets through Razorpay, and cash on delivery on most pin codes. We never see or store your card details.',NULL,0,1,1,0,'2026-09-30 19:59:54','2026-09-30 19:59:54'),(6,1,4,NULL,NULL,'Is cash on delivery available everywhere?','On most pin codes. If it is not available on yours, the option simply will not appear at checkout.',NULL,1,1,1,0,'2026-09-30 19:59:54','2026-09-30 19:59:54'),(7,1,5,NULL,NULL,'Should I patch test?','Yes, especially with actives. Put a small amount behind your ear or on your inner forearm and leave it 24 hours. If there is redness, itching or stinging that does not settle, stop using it.',NULL,0,1,1,0,'2026-09-30 19:59:54','2026-09-30 19:59:54'),(8,1,5,NULL,NULL,'How long before I see a difference?','It depends on what you are treating. Hydration shows in days; texture and tone take six to twelve weeks of consistent use. Anything promising more than that in less time is worth being suspicious of.',NULL,1,1,1,0,'2026-09-30 19:59:54','2026-09-30 19:59:54'),(9,1,1,NULL,NULL,'Are your products tested on animals?','No. Neither the finished products nor the ingredients we buy are tested on animals.',NULL,0,1,1,0,'2026-09-30 19:59:54','2026-09-30 19:59:54');
/*!40000 ALTER TABLE `cms_faqs` ENABLE KEYS */;
UNLOCK TABLES;

