INSERT INTO `cms_pages` (`id`, `shop_id`, `public_id`, `parent_id`, `slug`, `full_path`, `title`, `subtitle`, `page_type`, `template`, `locale`, `body_html`, `body_json`, `hero_media_id`, `status`, `published_at`, `scheduled_at`, `unpublish_at`, `requires_legal_review`, `reviewed_by_admin_id`, `reviewed_at`, `review_due_at`, `is_indexable`, `show_in_sitemap`, `preview_token`, `current_version`, `view_count`, `author_admin_id`, `updated_by_admin_id`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,1,'814c83ed-bd09-11f1-979d-38142846fb09',NULL,'shipping','/pages/shipping','Shipping & delivery','Where we ship, how long it takes, and what it costs.','policy','default','en-IN','<h2>Where we ship</h2><p>We ship across India. We do not ship internationally yet.</p><h2>Dispatch</h2><p>Orders placed before 2pm on a working day are usually dispatched the same day. Orders placed after that, or on a Sunday or public holiday, go out the next working day.</p><h2>Delivery times</h2><ul><li><strong>Metro cities</strong> — 2 to 4 working days</li><li><strong>Rest of India</strong> — 4 to 7 working days</li><li><strong>Remote pin codes</strong> — up to 10 working days</li></ul><h2>Charges</h2><p>Delivery is free on prepaid orders above Rs 999. Below that a flat delivery charge applies and is shown at checkout before you pay.</p><h2>Tracking</h2><p>You get a tracking link by SMS and email as soon as your parcel is handed to the courier. You can also track it from the <a href=\"/track\">track your order</a> page using your order number and phone.</p><p><em>Replace these timelines and charges with your own before publishing.</em></p>',NULL,NULL,'published','2026-09-30 19:59:54',NULL,NULL,0,NULL,NULL,NULL,1,1,NULL,1,0,NULL,NULL,'2026-09-30 19:59:54','2026-09-30 19:59:54',NULL),(2,1,'814d1348-bd09-11f1-979d-38142846fb09',NULL,'returns','/pages/returns','Returns & refunds','What can be returned, by when, and how the money comes back.','policy','default','en-IN','<h2>What you can return</h2><p>Unopened products in their original packaging can be returned within 7 days of delivery.</p><h2>What you cannot return</h2><p>For hygiene and safety reasons we cannot take back a product whose seal has been broken, unless it reached you damaged or is faulty. If something arrived damaged, tell us within 48 hours with a photo and we will replace it.</p><h2>How to start a return</h2><p>Reply to your order confirmation, or reach us on the <a href=\"/pages/contact\">contact page</a> with your order number. We arrange a pickup where the courier serves your pin code.</p><h2>Refunds</h2><p>Once the product is back with us and checked, the refund is issued to the original payment method within 5 to 7 working days. For cash on delivery orders we refund to a bank account you tell us.</p><p><em>Replace these windows and terms with your own before publishing.</em></p>',NULL,NULL,'published','2026-09-30 19:59:54',NULL,NULL,0,NULL,NULL,NULL,1,1,NULL,1,0,NULL,NULL,'2026-09-30 19:59:54','2026-09-30 19:59:54',NULL),(3,1,'814dbaaa-bd09-11f1-979d-38142846fb09',NULL,'contact','/pages/contact','Contact us','A real person reads these.','support','default','en-IN','<h2>Talk to us</h2><p>Email <a href=\"mailto:hello@veylor.co.in\">hello@veylor.co.in</a> and we answer within one working day.</p><h2>About an order</h2><p>Have your order number ready — it is in your confirmation SMS and starts with VEY. You can also check where a parcel is on the <a href=\"/track\">track your order</a> page without writing to us at all.</p><h2>About your skin</h2><p>If you are not sure whether a product suits you, write to us before you buy. We would rather talk you out of the wrong product than process a return.</p><p><em>Put your real address, GST number and support hours here before publishing.</em></p>',NULL,NULL,'published','2026-09-30 19:59:54',NULL,NULL,0,NULL,NULL,NULL,1,1,NULL,1,0,NULL,NULL,'2026-09-30 19:59:54','2026-09-30 19:59:54',NULL),(4,1,'814e3ca2-bd09-11f1-979d-38142846fb09',NULL,'privacy','/pages/privacy','Privacy policy','What we collect, why, and what you can ask us to delete.','policy','default','en-IN','<h2>What we collect</h2><p>Your name, phone number, email address and delivery address, so we can take an order and get it to you. Payment details are handled by our payment provider and never reach our servers.</p><h2>Why we keep it</h2><p>To fulfil your orders, to answer you when you write in, and — only if you have opted in — to tell you about products you saved or left in your bag.</p><h2>Marketing messages</h2><p>We only send marketing on WhatsApp, SMS or email if you have said yes. You can withdraw that at any time, and we stop.</p><h2>Your rights</h2><p>Under the Digital Personal Data Protection Act you can ask us for a copy of your data, ask us to correct it, or ask us to delete it. Write to <a href=\"mailto:privacy@veylor.co.in\">privacy@veylor.co.in</a>.</p><p><em>Have this reviewed before you publish it. This is a starting point, not legal advice.</em></p>',NULL,NULL,'published','2026-09-30 19:59:54',NULL,NULL,0,NULL,NULL,NULL,1,1,NULL,1,0,NULL,NULL,'2026-09-30 19:59:54','2026-09-30 19:59:54',NULL),(5,1,'814ebd00-bd09-11f1-979d-38142846fb09',NULL,'about','/pages/about','Our story','Formulated in India, for Indian skin and Indian weather.','about','default','en-IN','<h2>Why Veylor exists</h2><p>Most of what reaches Indian shelves was formulated for other climates and other skin. Humidity, hard water, sun that does not let up for eight months of the year — these change what a product has to do.</p><h2>How we formulate</h2><p>Small ingredient lists, concentrations we are willing to print on the box, and no claim we cannot point to evidence for. Every product lists its full INCI, and every article in our <a href=\"/journal\">journal</a> that touches on safety carries the name of the person who reviewed it.</p><p><em>Write your own story here — this is a placeholder.</em></p>',NULL,NULL,'published','2026-09-30 19:59:54',NULL,NULL,0,NULL,NULL,NULL,1,1,NULL,1,0,NULL,NULL,'2026-09-30 19:59:54','2026-09-30 19:59:54',NULL);
/*!40000 ALTER TABLE `cms_pages` ENABLE KEYS */;
