ormulations\", \"background\": \"ivory\", \"media_side\": \"left\", \"panel_icon\": \"leaf\", \"panel_quote\": \"Every percentage on the front of the box is the percentage in the bottle.\"}',NULL,'2026-09-30 19:59:56','2026-09-30 19:59:56',NULL),(5,1,'collection_tiles','page','Home — shop by edit',NULL,NULL,NULL,'split',NULL,'md','md','{\"source\": \"auto\", \"columns\": 3, \"eyebrow\": \"Curated\", \"heading\": \"Shop by edit\", \"background\": \"none\"}',NULL,'2026-09-30 19:59:56','2026-09-30 19:59:56',NULL),(6,1,'banner_slot','page','Home — campaign slot',NULL,NULL,NULL,'split',NULL,'md','md','{\"placement\": \"home_carousel\"}',NULL,'2026-09-30 19:59:56','2026-09-30 19:59:56',NULL),(7,1,'shelf_embed','page','Home — new in shelf',NULL,NULL,NULL,'split',NULL,'md','md','{\"shelf\": 2}',NULL,'2026-09-30 19:59:56','2026-09-30 19:59:56',NULL);
