INSERT INTO `notification_templates` (`id`, `shop_id`, `event_key`, `channel`, `category`, `locale`, `name`, `description`, `subject`, `preheader`, `header_text`, `body`, `footer_text`, `buttons`, `provider`, `sender_id`, `provider_template_id`, `dlt_template_id`, `approval_status`, `approval_note`, `approved_at`, `variables`, `sample_variables`, `is_transactional`, `is_active`, `last_used_at`, `usage_count`, `updated_by_admin_id`, `created_by_admin_id`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,1,'otp.login','sms','authentication','en-IN','Login OTP — SMS',NULL,NULL,NULL,NULL,'{{otp}} is your Veylor verification code. Valid for 5 minutes. Do not share it.',NULL,NULL,NULL,2,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(2,1,'otp.login','whatsapp','authentication','en-IN','Login OTP — WhatsApp',NULL,NULL,NULL,NULL,'{{otp}} is your Veylor verification code. Valid for 5 minutes.',NULL,NULL,NULL,3,NULL,NULL,'approved',NULL,'2026-09-30 19:59:24',NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(3,1,'order.confirmed','sms','transactional','en-IN','Order confirmed — SMS',NULL,NULL,NULL,NULL,'Order {{order_number}} confirmed. Track it at {{tracking_url}}',NULL,NULL,NULL,2,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(4,1,'order.confirmed','whatsapp','transactional','en-IN','Order confirmed — WhatsApp',NULL,NULL,NULL,NULL,'Thank you. Order {{order_number}} is confirmed.',NULL,NULL,NULL,3,NULL,NULL,'approved',NULL,'2026-09-30 19:59:24',NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(5,1,'order.confirmed','email','transactional','en-IN','Order confirmed — Email',NULL,'Your Veylor order {{order_number}}',NULL,NULL,'Hi {{first_name}},\r\n\r\nThank you — your order {{order_number}} is confirmed, and we are getting it ready.\r\n\r\nTotal: {{order_total}}\r\n\r\nWe will write again the moment it ships.\r\n\r\n— {{shop_name}}',NULL,NULL,NULL,1,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(6,1,'order.shipped','sms','transactional','en-IN','Order shipped — SMS',NULL,NULL,NULL,NULL,'Order {{order_number}} has shipped. AWB {{awb}}. Track: {{tracking_url}}',NULL,NULL,NULL,2,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(7,1,'order.shipped','whatsapp','transactional','en-IN','Order shipped — WhatsApp',NULL,NULL,NULL,NULL,'Your Veylor order is on its way.',NULL,NULL,NULL,3,NULL,NULL,'approved',NULL,'2026-09-30 19:59:24',NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(8,1,'order.out_for_delivery','sms','transactional','en-IN','Out for delivery — SMS',NULL,NULL,NULL,NULL,'Order {{order_number}} is out for delivery today.',NULL,NULL,NULL,2,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(9,1,'order.delivered','whatsapp','transactional','en-IN','Delivered — WhatsApp',NULL,NULL,NULL,NULL,'Your Veylor order has been delivered.',NULL,NULL,NULL,3,NULL,NULL,'approved',NULL,'2026-09-30 19:59:24',NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(10,1,'order.cancelled','email','transactional','en-IN','Order cancelled — Email',NULL,'Order {{order_number}} cancelled',NULL,NULL,'Hi {{first_name}},\r\n\r\nYour order {{order_number}} has been cancelled, and nothing further will be charged. Anything already paid is refunded to the original payment method.\r\n\r\nIf this was not you, reply to this email and we will look into it.\r\n\r\n— {{shop_name}}',NULL,NULL,NULL,1,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(11,1,'payment.failed','email','transactional','en-IN','Payment failed — Email',NULL,'We could not complete your payment',NULL,NULL,'Hi {{first_name}},\r\n\r\nThe payment for order {{order_number}} did not go through, so we have not been able to start on it. Nothing has been charged.\r\n\r\nYou can try again here: {{link}}\r\n\r\n— {{shop_name}}',NULL,NULL,NULL,1,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(12,1,'refund.processed','email','transactional','en-IN','Refund processed — Email',NULL,'Your refund for {{order_number}}',NULL,NULL,'Hi {{first_name}},\r\n\r\nYour refund for order {{order_number}} has been processed: {{order_total}}. Banks usually take three to five working days to show it.\r\n\r\n— {{shop_name}}',NULL,NULL,NULL,1,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(13,1,'cart.abandoned','email','marketing','en-IN','Abandoned cart — Email',NULL,'You left something behind',NULL,NULL,'Hi {{name}}, you left {{product_name}} behind. It is still waiting for you: {{product_url}}\r\n\r\nNot interested in these? {{unsubscribe_url}}',NULL,NULL,NULL,1,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,0,0,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(14,1,'review.invite','email','marketing','en-IN','Review invitation — Email',NULL,'How is your Veylor routine going?',NULL,NULL,'Hi {{first_name}},\r\n\r\nYou ordered from us a little while ago. If you have a minute, we would love to know how it is working for you — it helps everyone who reads it before buying.\r\n\r\nLeave a review: {{link}}\r\n\r\n— {{shop_name}}\r\nNot interested in these? {{unsubscribe_url}}',NULL,NULL,NULL,1,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,0,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(15,1,'stock.back_in_stock','email','marketing','en-IN','Back in stock — Email',NULL,'{{product_name}} is back',NULL,NULL,'Hi {{first_name}},\r\n\r\n{{product_name}} is back in stock. It went quickly last time, so this is the early word rather than an announcement.\r\n\r\nHave a look: {{link}}\r\n\r\n— {{shop_name}}\r\nNot interested in these? {{unsubscribe_url}}',NULL,NULL,NULL,1,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,0,1,NULL,0,NULL,NULL,'2026-09-30 19:59:24','2026-09-30 19:59:58',NULL),(16,1,'cart.abandoned','whatsapp','marketing','en','Saved but not bought — WhatsApp',NULL,NULL,NULL,NULL,'Hi {{name}}, you saved {{product_name}} at Veylor but haven\'t ordered it yet. It\'s still available: {{product_url}}. Reply STOP to stop receiving these.',NULL,NULL,NULL,3,NULL,NULL,'approved',NULL,'2026-09-30 19:59:54',NULL,NULL,0,1,NULL,0,NULL,NULL,'2026-09-30 19:59:54','2026-09-30 19:59:58',NULL),(17,1,'gift_card.issued','email','transactional','en-IN','Gift card — Email',NULL,'Your {{gift_card_value}} {{shop_name}} gift card',NULL,NULL,'Hi {{first_name}},\n\n{{gift_card_message}}You have a {{gift_card_value}} gift card for {{shop_name}}.\n\nCode: {{gift_card_code}}\n{{gift_card_expiry}}\nUse it at checkout, or see its balance any time: {{gift_card_url}}\n\n— {{shop_name}}',NULL,NULL,NULL,NULL,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 20:00:44','2026-09-30 20:00:44',NULL),(18,1,'gift_card.issued','sms','transactional','en-IN','Gift card — SMS',NULL,NULL,NULL,NULL,'{{shop_name}}: your {{gift_card_value}} gift card code is {{gift_card_code}}. Balance: {{gift_card_url}}',NULL,NULL,NULL,NULL,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 20:00:44','2026-09-30 20:00:44',NULL),(19,1,'gift_card.issued','whatsapp','transactional','en-IN','Gift card — WhatsApp',NULL,NULL,NULL,NULL,'You have a {{gift_card_value}} gift card for {{shop_name}}. Code: {{gift_card_code}}. See it any time: {{gift_card_url}}',NULL,NULL,NULL,NULL,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 20:00:44','2026-09-30 20:00:44',NULL),(20,1,'privacy.request_verify','email','transactional','en-IN','Privacy request: confirm it is you — Email',NULL,'Confirm your privacy request to {{shop_name}}',NULL,NULL,'Hi,\n\nWe received a request to {{request_action}} the personal data {{shop_name}} holds about {{contact}}.\n\nIf this was you, confirm it here (the link works for 48 hours):\n{{link}}\n\nIf it was not you, ignore this email — nothing will happen.\n\nReference: {{reference}}\n\n— {{shop_name}}',NULL,NULL,NULL,NULL,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 20:00:46','2026-09-30 20:00:46',NULL),(21,1,'privacy.request_received','email','transactional','en-IN','Privacy request received — Email',NULL,'We have your privacy request {{reference}}',NULL,NULL,'Hi {{first_name}},\n\nWe have your request to {{request_action}} your personal data, reference {{reference}}. We will respond by {{due_date}}.\n\nQuestions about it: {{privacy_contact}}\n\n— {{shop_name}}',NULL,NULL,NULL,NULL,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 20:00:46','2026-09-30 20:00:46',NULL),(22,1,'privacy.request_completed','email','transactional','en-IN','Privacy request completed — Email',NULL,'Your privacy request {{reference}} is complete',NULL,NULL,'Hi {{first_name}},\n\n{{outcome}}\n\n{{link_line}}If you are not satisfied with how we handled it, contact {{privacy_contact}}.\n\n— {{shop_name}}',NULL,NULL,NULL,NULL,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 20:00:46','2026-09-30 20:00:46',NULL),(23,1,'staff.privacy_request','email','transactional','en-IN','New privacy request — Staff email',NULL,'New privacy request {{reference}}',NULL,NULL,'{{title}}\n\n{{body}}\n\n— {{shop_name}}',NULL,NULL,NULL,NULL,NULL,NULL,'not_required',NULL,NULL,NULL,NULL,1,1,NULL,0,NULL,NULL,'2026-09-30 20:00:46','2026-09-30 20:00:46',NULL);
